import { Link } from 'react-router-dom';

import styles from './Button.module.css';

/**
 * Универсальный компонент кнопки с поддержкой навигации и ссылок.
 *
 * Может отображаться как обычный `<button>`, `<Link>` из React Router или `<a>` для внешних ссылок.
 * Поддерживает темы оформления (светлая/тёмная), кастомные размеры и стили.
 *
 * После нажатия:
 * - Выполняет переданную функцию `onClick`.
 * - При `disabled` — блокирует взаимодействие и визуально отключает элемент.
 *
 * Поддерживает:
 * - Переход по маршруту (`to`) с помощью `react-router-dom`.
 * - Переход по внешней ссылке (`href`).
 * - Доступность: фокусировка и активация через клавиатуру (Enter/пробел).
 * - Полное кастомизирование через `className`, `style`, `width`, `height`.
 * - Семантическую корректность: использует `<button>`, `<a>` или `<Link>` в зависимости от контекста.
 */

export const Button = ({
  children,
  to,
  href,
  type = 'button',
  form,
  onClick,
  disabled,
  width,
  height,
  style,
  frame = 'light', // 'light' или 'dark'
  className,
  ...rest
}) => {
  const buttonStyle = { width, height, ...style };
  const frameClass = frame === 'dark' ? styles.dark : '';
  // Обработчик для имитации клика по Enter/Space
  const handleKeyDown = (e) => {
    if (disabled) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (onClick) onClick(e);
    }
  };

  if (to) {
    return (
      <Link
        to={to}
        className={`${styles.button} ${frameClass} ${className}`}
        style={buttonStyle}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        onClick={disabled ? (e) => e.preventDefault() : onClick}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        <span className={styles.buttonText}>{children}</span>
      </Link>
    );
  }

  if (href) {
    return (
      <a
        href={disabled ? undefined : href}
        className={`${styles.button} ${frameClass} ${className}`}
        style={buttonStyle}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled}
        onClick={disabled ? (e) => e.preventDefault() : onClick}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        <span className={styles.buttonText}>{children}</span>
      </a>
    );
  }

  return (
    <button
      type={type}
      form={form}
      onClick={onClick}
      disabled={disabled}
      className={`${styles.button} ${className}`}
      style={buttonStyle}
      {...rest}
    >
      <span className={styles.buttonText}>{children}</span>
    </button>
  );
};
