import { useRef, useState } from 'react';
import Draggable from 'react-draggable';

import { FiCheck, FiChevronDown, FiChevronUp, FiCopy } from 'react-icons/fi';

import styles from './CalcWindow.module.css';

export const CalcWindow = () => {
  const dragRef = useRef(null);
  const [collapsed, setCollapsed] = useState(false);

  const [screenWidth, setScreenWidth] = useState('');
  const [screenHeight, setScreenHeight] = useState('');
  const [blockWidth, setBlockWidth] = useState('');
  const [blockHeight, setBlockHeight] = useState('');
  const [copied, setCopied] = useState('');

  // Сетка
  const [showGrid, setShowGrid] = useState(false);
  const [gridWidth, setGridWidth] = useState(16);
  const [gridHeight, setGridHeight] = useState(16);
  const [gridLineWidth, setGridLineWidth] = useState(1);

  const calcWidthVW = () => {
    if (!screenWidth || !blockWidth) return '';
    return ((blockWidth / screenWidth) * 100).toFixed(2);
  };

  const calcHeightVH = () => {
    if (!screenHeight || !blockHeight) return '';
    return ((blockHeight / screenHeight) * 100).toFixed(2);
  };

  const handleCopy = (text, type) => {
    navigator.clipboard.writeText(text);
    setCopied(type);
    setTimeout(() => setCopied(''), 1200);
  };

  const widthValue = calcWidthVW();
  const heightValue = calcHeightVH();

  // Безопасные значения для размера ячейки сетки
  const gw = Math.max(2, Number(gridWidth) || 16);
  const gh = Math.max(2, Number(gridHeight) || 16);

  return (
    <>
      {/* Полноэкранная сетка */}
      <div
        className={`${styles.gridOverlay} ${showGrid ? styles.gridVisible : ''}`}
        style={{
          backgroundSize: `${gw}px 100%, 100% ${gh}px`,
          backgroundImage: `
      repeating-linear-gradient(
        to right,
        #ffffff3a,
        #ffffff3a ${gridLineWidth}px,
        transparent ${gridLineWidth}px,
        transparent ${gw}px
      ),
      repeating-linear-gradient(
        to bottom,
        #ffffff3a,
        #ffffff3a ${gridLineWidth}px,
        transparent ${gridLineWidth}px,
        transparent ${gh}px
      )
    `,
        }}
        aria-hidden="true"
      />

      <Draggable nodeRef={dragRef}>
        <div ref={dragRef} className={styles.container}>
          <div className={styles.headerRow}>
            <h4>📐 Adaptive Calculator</h4>
            <button
              className={styles.collapseBtn}
              onClick={() => setCollapsed((c) => !c)}
              title={collapsed ? 'Развернуть' : 'Свернуть'}
              aria-label={collapsed ? 'Развернуть калькулятор' : 'Свернуть калькулятор'}
              type="button"
            >
              {collapsed ? <FiChevronDown size={20} /> : <FiChevronUp size={20} />}
            </button>
          </div>
          {!collapsed && (
            <>
              <div className={styles.inputGroup}>
                <label>Screen Width(px):</label>
                <input
                  type="number"
                  value={screenWidth}
                  onChange={(e) => setScreenWidth(+e.target.value)}
                />
              </div>

              <div className={styles.inputGroup}>
                <label>Screen Height(px):</label>
                <input
                  type="number"
                  value={screenHeight}
                  onChange={(e) => setScreenHeight(+e.target.value)}
                />
              </div>

              <div className={styles.inputGroup}>
                <label>Block Width(px):</label>
                <input
                  type="number"
                  value={blockWidth}
                  onChange={(e) => setBlockWidth(+e.target.value)}
                />
              </div>

              <div className={styles.inputGroup}>
                <label>Block Height(px):</label>
                <input
                  type="number"
                  value={blockHeight}
                  onChange={(e) => setBlockHeight(+e.target.value)}
                />
              </div>

              <div className={styles.result}>
                <strong>Result:</strong>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <p>Width: {widthValue && `${widthValue}vw`}</p>
                  {widthValue && (
                    <button
                      className={styles.copyBtn}
                      onClick={() => handleCopy(`width: ${widthValue}vw;`, 'width')}
                      title="Скопировать CSS"
                    >
                      {copied === 'width' ? (
                        <FiCheck size={18} color="#4caf50" />
                      ) : (
                        <FiCopy size={18} />
                      )}
                    </button>
                  )}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <p>Height: {heightValue && `${heightValue}vh`}</p>
                  {heightValue && (
                    <button
                      className={styles.copyBtn}
                      onClick={() => handleCopy(`height: ${heightValue}vh;`, 'height')}
                      title="Скопировать CSS"
                    >
                      {copied === 'height' ? (
                        <FiCheck size={18} color="#4caf50" />
                      ) : (
                        <FiCopy size={18} />
                      )}
                    </button>
                  )}
                </div>
              </div>

              {/* Управление сеткой */}
              <div className={styles.gridControls}>
                <label className={styles.switchRow}>
                  <input
                    type="checkbox"
                    checked={showGrid}
                    onChange={(e) => setShowGrid(e.target.checked)}
                  />
                  <span>Показать сетку на экране</span>
                </label>

                <div className={styles.gridInputs}>
                  <div className={styles.inputGroup}>
                    <label>Grid Width(px):</label>
                    <input
                      type="number"
                      min={2}
                      value={gridWidth}
                      onChange={(e) => setGridWidth(+e.target.value)}
                    />
                  </div>
                  <div className={styles.inputGroup}>
                    <label>Grid Height(px):</label>
                    <input
                      type="number"
                      min={2}
                      value={gridHeight}
                      onChange={(e) => setGridHeight(+e.target.value)}
                    />
                  </div>
                  <div className={styles.inputGroup}>
                    <label>Grid Line(px):</label>
                    <input
                      type="number"
                      min={1}
                      max={10}
                      value={gridLineWidth}
                      onChange={(e) => setGridLineWidth(+e.target.value)}
                    />
                  </div>
                </div>
              </div>

              {/* Бейдж */}
              <div className={styles.brandBadge}>разработано специально для ForwardTrading</div>
            </>
          )}{' '}
        </div>
      </Draggable>
    </>
  );
};
